package main

import "strings"

const replayWorksheetTSPath = "console/src/features/reliability/replay-worksheet.ts"

func writeReplayWorksheetTS() error {
	body, err := renderReplayWorksheetTS()
	if err != nil {
		return err
	}
	return writeRenderedFile(replayWorksheetTSPath, body)
}

func renderReplayWorksheetTS() ([]byte, error) {
	lines := append(replayWorksheetPreludeLines(), replayWorksheetBodyLines()...)
	return []byte(strings.Join(lines, "\n") + "\n"), nil
}

func replayWorksheetPreludeLines() []string {
	return []string{
		"// Code generated by go run ./internal/tools/observabilitydash. Do not edit by hand.",
		"",
		"import { type ReliabilityCatalogEntryValue, reliabilityCatalog } from './reliability-catalog'",
		"",
		"export const replayWorksheetDownloadName = 'attune-slo-replay-template.md' as const",
		"",
		"function escapeMarkdownTableCell(value: string) {",
		"  return value.replaceAll('|', '\\\\|').replaceAll('\\n', ' ')",
		"}",
		"",
		"function replayHeaderRow(label: string, value: string) {",
		"  return `| ${label} | ${value} |`",
		"}",
		"",
		"function replayComparisonPlaceholder(key: string, suffix: 'observation' | 'verdict') {",
		"  return `\\`{{ ${key}_${suffix} }}\\``",
		"}",
		"",
		"function replayScopeLabel(scope: ReliabilityCatalogEntryValue['scope']) {",
		"  switch (scope) {",
		"    case 'tenant':",
		"      return 'tenant'",
		"    case 'destination_type':",
		"      return 'destination type'",
		"    case 'global':",
		"      return 'global'",
		"    default:",
		"      return (scope as string).replaceAll('_', ' ')",
		"  }",
		"}",
		"",
		"function reliabilityReplayLens(key: ReliabilityCatalogEntryValue['key']) {",
		"  switch (key) {",
		"    case 'ingest_service':",
		"      return 'tenant / source / result'",
		"    case 'enrichment_latency':",
		"      return 'tenant / dims_mode / result'",
		"    case 'outbox_delivery':",
		"      return 'destination_type / reason'",
		"    case 'oidc_login':",
		"      return 'result / auth flow'",
		"    case 'apikey_access':",
		"      return 'tenant / denial class'",
		"    case 'mcp_tool':",
		"      return 'tenant / tool / result'",
		"    case 'gdpr_job':",
		"      return 'tenant / request_type / result'",
		"    default:",
		"      return 'tenant / result'",
		"  }",
		"}",
		"",
		"function reliabilityRunbookURL(alertName: string) {",
		"  return `https://github.com/Phixsura/attune/blob/main/observability/runbooks.md#${alertName.toLowerCase()}`",
		"}",
		"",
		"function reliabilityComparisonRow(slo: ReliabilityCatalogEntryValue) {",
		"  return `| ${slo.title} | ${slo.policySummary} | ${reliabilityReplayLens(slo.key)} | ${slo.budgetExceptionPolicy} | ${replayComparisonPlaceholder(slo.key, 'observation')} | ${replayComparisonPlaceholder(slo.key, 'verdict')} | [Open runbook](${reliabilityRunbookURL(slo.alertName)}) |`",
		"}",
		"",
		"function reliabilityCatalogReferenceRow(slo: ReliabilityCatalogEntryValue) {",
		"  return `| ${slo.title} | ${slo.owner} | ${slo.escalation} | ${replayScopeLabel(slo.scope)} | ${(slo.objective * 100).toFixed(1)}% | ${reliabilityReplayLens(slo.key)} | ${slo.budgetExceptionPolicy} | [Open runbook](${reliabilityRunbookURL(slo.alertName)}) |`",
		"}",
		"",
	}
}

func replayWorksheetBodyLines() []string {
	return []string{
		"export function buildReplayWorksheetMarkdown(tenantName: string, dashboardHref: string) {",
		"  const lines = [",
		"    '# Attune SLO Replay / Backfill Report Template',",
		"    '',",
		"    'Use this worksheet to compare a historical outage against the current SLO policy. Fill the incident header first, then use the generated comparison matrix to capture burn history, remaining budget, routing metadata, and the most likely replay lens.',",
		"    '',",
		"    '## Incident header',",
		"    '',",
		"    '| Field | Value |',",
		"    '| --- | --- |',",
		"    replayHeaderRow('Incident title', '`{{ incident_title }}`'),",
		"    replayHeaderRow('Incident window', '`{{ incident_window }}`'),",
		"    replayHeaderRow('Primary tenant', `\\`${escapeMarkdownTableCell(tenantName)}\\``),",
		"    replayHeaderRow('Primary SLO', '`{{ primary_slo }}`'),",
		"    replayHeaderRow('Likely dependency', '`{{ likely_dependency }}`'),",
		"    replayHeaderRow('Owner', '`{{ owner }}`'),",
		"    replayHeaderRow('Escalation', '`{{ escalation }}`'),",
		"    replayHeaderRow('Runbook', '[Open runbook]({{ runbook_url }})'),",
		"    replayHeaderRow('Dashboard', `[Open tenant impact dashboard](${dashboardHref})`),",
		"    '',",
		"    '## Comparison matrix',",
		"    '',",
		"    'Use the generated policy columns as the control. Fill the historical observation and verdict fields from the incident window.',",
		"    '',",
		"    '| SLO | Current policy | Replay lens | Budget exception | Historical observation | Verdict | Runbook |',",
		"    '| --- | --- | --- | --- | --- | --- | --- |',",
		"    ...reliabilityCatalog.map(reliabilityComparisonRow),",
		"    '',",
		"    '## Replay checklist',",
		"    '',",
		"    '- Open the incident window in Grafana and keep the same time range on Burn trend, Burn history, and Remaining budget.',",
		"    '- Record the dominant tenant, source/result, dependency, or destination type that explains the spike, then fill the comparison matrix verdict column.',",
		"    '- Compare the current 5m / 1h burn with the 7d / 30d averages to separate a spike from a sustained regression.',",
		"    '- Copy owner, escalation, and runbook metadata from the routing table into the incident review.',",
		"    '- Decide whether the historical event would still page under the current fast-burn and slow-burn thresholds.',",
		"    '',",
		"    '## SLO catalog reference',",
		"    '',",
		"    '| SLO | Owner | Escalation | Scope | Objective | Replay lens | Budget exception | Runbook |',",
		"    '| --- | --- | --- | --- | --- | --- | --- | --- |',",
		"    ...reliabilityCatalog.map(reliabilityCatalogReferenceRow),",
		"    '',",
		"    '## Report notes',",
		"    '',",
		"    '- Current policy thresholds: fast burn 14.4x on 5m and 1h; slow burn 6x on 30m and 6h.',",
		"    '- Use the same owner / escalation / runbook metadata that appears in the routing table and comparison matrix.',",
		"    '- Attach the final report to the incident review or backfill ticket so the replay stays traceable.',",
		"    '',",
		"  ]",
		"  return `${lines.join('\\n')}\\n`",
		"}",
		"",
		"export function replayWorksheetDownloadHref(tenantName: string, dashboardHref: string) {",
		"  return `data:text/markdown;charset=utf-8,${encodeURIComponent(buildReplayWorksheetMarkdown(tenantName, dashboardHref))}`",
		"}",
	}
}
